import sqlite3, re
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
print("user_version", con.execute("pragma user_version").fetchone())
print("--- views/triggers referencing base_parameters, with status filter?")
for name, typ, sql in con.execute("select name,type,sql from sqlite_master where sql like '%base_parameters%' and type in ('view','trigger')"):
    print(f"{typ} {name}: status-filter={'status' in sql}")
print("--- FKs into base_parameters")
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    for fk in con.execute(f'PRAGMA foreign_key_list("{t}")'):
        if fk[2]=='base_parameters':
            cols=[c[1] for c in con.execute(f'PRAGMA table_info("{t}")')]
            print(t, fk[3], '->', fk[4], 'notes' in cols)
print("--- UNWRITABLE derivation")
empty = {t for (t,) in con.execute("select name from sqlite_master where type='table'") if con.execute(f'select count(*) from "{t}"').fetchone()[0]==0}
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    dead = {f[3] for f in con.execute(f'PRAGMA foreign_key_list("{t}")') if f[2] in empty}
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1] in dead and c[3]: print(f"UNWRITABLE  {t}.{c[1]} -> empty table")
print("--- extraction_method CHECK / extraction_status")
sql = con.execute("select sql from sqlite_master where name='source_value_extractions'").fetchone()[0]
for m in re.finditer(r'(extraction_method|extraction_status)[^\n]*', sql): print(m.group(0)[:200])
print("--- term_aliases DDL")
print(con.execute("select sql from sqlite_master where name='term_aliases'").fetchone()[0][:900])
print("--- counts")
for t in ('base_parameters','observed_terms','source_scans','pipeline_runs','evidence_sources','parameter_declinations','specifications','term_catalogue_origins','extraction_follow_ups'):
    print(t, con.execute(f'select count(*) from {t}').fetchone()[0])
print("--- base_parameters rows")
for r in con.execute("select parameter_id, term_id, status, merged_into, accessibility_direction from base_parameters"): print(r)
print("--- created_at formats")
for r in con.execute("select created_at from evidence_sources order by created_at desc limit 3"): print(r)
print(con.execute("select count(*) from evidence_sources where created_at >= '2026-10-10'").fetchone())
print("--- method values live")
print(con.execute("select extraction_method, count(*) from source_value_extractions group by 1").fetchall())
print("--- orphans R17")
print(con.execute("select ref_id from evidence_sources e where not exists (select 1 from search_admissions a where a.ref_id=e.ref_id)").fetchall())
